import{_ as s,o as t,c as e,a0 as n}from"./chunks/framework.DQOulFGV.js";const c=JSON.parse('{"title":"KRaft 模式与去 ZooKeeper","description":"","frontmatter":{"doc_id":"kafka-KRaft模式与去ZooKeeper","title":"KRaft 模式与去 ZooKeeper"},"headers":[],"relativePath":"kafka/11-KRaft模式与去ZooKeeper.md","filePath":"kafka/11-KRaft模式与去ZooKeeper.md"}'),i={name:"kafka/11-KRaft模式与去ZooKeeper.md"};function r(l,a,p,o,h,d){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="kraft-模式与去-zookeeper" tabindex="-1">KRaft 模式与去 ZooKeeper <a class="header-anchor" href="#kraft-模式与去-zookeeper" aria-label="Permalink to &quot;KRaft 模式与去 ZooKeeper&quot;">​</a></h1><hr><h2 id="_1-zookeeper-模式的痛点" tabindex="-1">1. ZooKeeper 模式的痛点 <a class="header-anchor" href="#_1-zookeeper-模式的痛点" aria-label="Permalink to &quot;1. ZooKeeper 模式的痛点&quot;">​</a></h2><p>Kafka 早期依赖 ZooKeeper 存储集群元数据，随着规模增大，问题逐渐暴露：</p><table tabindex="0"><thead><tr><th>痛点</th><th>说明</th></tr></thead><tbody><tr><td><strong>双系统运维</strong></td><td>需要同时维护 Kafka 集群和 ZooKeeper 集群，运维复杂度翻倍</td></tr><tr><td><strong>元数据瓶颈</strong></td><td>ZooKeeper 的写入吞吐有限，大规模集群（百万分区）时元数据操作成为瓶颈</td></tr><tr><td><strong>Controller 重启慢</strong></td><td>Controller 宕机后，新 Controller 需要从 ZooKeeper 全量加载元数据，分区数越多越慢（可能需要数分钟）</td></tr><tr><td><strong>ZooKeeper 本身的问题</strong></td><td>ZooKeeper 的 ZAB 协议与 Kafka 的 Raft 是两套不同的一致性协议，增加了系统复杂性</td></tr><tr><td><strong>扩展性上限</strong></td><td>ZooKeeper 实测在 20 万分区左右开始出现性能问题</td></tr></tbody></table><hr><h2 id="_2-kraft-是什么" tabindex="-1">2. KRaft 是什么？ <a class="header-anchor" href="#_2-kraft-是什么" aria-label="Permalink to &quot;2. KRaft 是什么？&quot;">​</a></h2><p><strong>KRaft</strong>（Kafka Raft）是 Kafka 内置的基于 <strong>Raft 协议</strong>的元数据管理方案，完全替代 ZooKeeper。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KRaft = Kafka + Raft</span></span>
<span class="line"><span>目标：让 Kafka 自己管理自己的元数据，不再依赖外部系统</span></span></code></pre></div><p><strong>发展历程</strong>：</p><table tabindex="0"><thead><tr><th>版本</th><th>里程碑</th></tr></thead><tbody><tr><td>Kafka 2.8（2021）</td><td>KRaft 预览版（不建议生产使用）</td></tr><tr><td>Kafka 3.3（2022）</td><td>KRaft 正式 GA，可用于生产</td></tr><tr><td>Kafka 3.5（2023）</td><td>ZooKeeper 模式标记为 Deprecated</td></tr><tr><td>Kafka 4.0（2024）</td><td>完全移除 ZooKeeper 支持</td></tr></tbody></table><hr><h2 id="_3-kraft-架构" tabindex="-1">3. KRaft 架构 <a class="header-anchor" href="#_3-kraft-架构" aria-label="Permalink to &quot;3. KRaft 架构&quot;">​</a></h2><h3 id="_3-1-节点角色" tabindex="-1">3.1 节点角色 <a class="header-anchor" href="#_3-1-节点角色" aria-label="Permalink to &quot;3.1 节点角色&quot;">​</a></h3><p>KRaft 模式下，Kafka 节点有三种角色：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph &quot;KRaft 集群&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        subgraph &quot;Controller 节点（3个，组成 Raft 集群）&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            C1[&quot;Controller 1\\n（Active Leader）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            C2[&quot;Controller 2\\n（Follower）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            C3[&quot;Controller 3\\n（Follower）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        subgraph &quot;Broker 节点（负责数据存储）&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            B1[Broker 1]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            B2[Broker 2]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            B3[Broker 3]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1 &lt;--&gt;|Raft 协议同步元数据| C2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1 &lt;--&gt;|Raft 协议同步元数据| C3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1 --&gt;|元数据推送| B1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1 --&gt;|元数据推送| B2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1 --&gt;|元数据推送| B3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre></div><table tabindex="0"><thead><tr><th>角色</th><th>职责</th><th>说明</th></tr></thead><tbody><tr><td><strong>Controller（Active）</strong></td><td>处理所有元数据写入请求</td><td>Raft Leader，同一时刻只有一个</td></tr><tr><td><strong>Controller（Follower）</strong></td><td>同步元数据，参与选举</td><td>Raft Follower，可接管 Leader</td></tr><tr><td><strong>Broker</strong></td><td>数据存储与读写</td><td>从 Active Controller 拉取最新元数据</td></tr></tbody></table><blockquote><p><strong>部署灵活性</strong>：Controller 和 Broker 可以合并部署（小集群），也可以分离部署（大集群，推荐）。</p></blockquote><h3 id="_3-2-元数据存储-metadata-topic" tabindex="-1">3.2 元数据存储：@metadata Topic <a class="header-anchor" href="#_3-2-元数据存储-metadata-topic" aria-label="Permalink to &quot;3.2 元数据存储：@metadata Topic&quot;">​</a></h3><p>KRaft 将所有元数据存储在一个内部 Topic <code>__cluster_metadata</code> 中，以 <strong>Raft 日志</strong>的形式持久化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__cluster_metadata 日志内容（示意）：</span></span>
<span class="line"><span>offset=1: RegisterBrokerRecord（Broker 1 注册）</span></span>
<span class="line"><span>offset=2: RegisterBrokerRecord（Broker 2 注册）</span></span>
<span class="line"><span>offset=3: TopicRecord（创建 Topic &quot;orders&quot;）</span></span>
<span class="line"><span>offset=4: PartitionRecord（分区 0 分配到 Broker 1）</span></span>
<span class="line"><span>offset=5: PartitionChangeRecord（Leader 从 Broker 1 变为 Broker 2）</span></span>
<span class="line"><span>...</span></span></code></pre></div><p><strong>优势</strong>：</p><ul><li>元数据变更以日志形式追加，天然支持回放和审计</li><li>Broker 通过拉取日志同步元数据，无需 ZooKeeper Watch 机制</li><li>Controller 重启后只需从日志末尾继续，不需要全量加载</li></ul><hr><h2 id="_4-raft-协议简介" tabindex="-1">4. Raft 协议简介 <a class="header-anchor" href="#_4-raft-协议简介" aria-label="Permalink to &quot;4. Raft 协议简介&quot;">​</a></h2><p>KRaft 基于 Raft 协议实现 Controller 的高可用选举和元数据一致性。</p><h3 id="_4-1-leader-选举" tabindex="-1">4.1 Leader 选举 <a class="header-anchor" href="#_4-1-leader-选举" aria-label="Permalink to &quot;4.1 Leader 选举&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C1 as Controller 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C2 as Controller 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C3 as Controller 3</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C1,C3: 初始状态，C1 是 Leader</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C1: C1 宕机，C2/C3 超时未收到心跳</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C2-&gt;&gt;C2: 增加 epoch（任期号），变为 Candidate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C2-&gt;&gt;C3: 发起投票请求（epoch=2）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C3--&gt;&gt;C2: 投票给 C2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C2: 获得多数票（2/3），成为新 Leader</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C2-&gt;&gt;C3: 发送心跳，同步元数据日志</span></span></code></pre></div><p><strong>Raft 选举规则</strong>：</p><ol><li>节点超时未收到 Leader 心跳，增加 epoch，发起选举</li><li>获得 <strong>多数票（&gt;N/2）</strong> 的节点成为新 Leader</li><li>新 Leader 同步最新日志后，开始处理请求</li></ol><h3 id="_4-2-日志复制" tabindex="-1">4.2 日志复制 <a class="header-anchor" href="#_4-2-日志复制" aria-label="Permalink to &quot;4.2 日志复制&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写入流程（元数据变更）：</span></span>
<span class="line"><span>1. 客户端（Broker）向 Active Controller 发送元数据变更请求</span></span>
<span class="line"><span>2. Active Controller 将变更写入本地 Raft 日志</span></span>
<span class="line"><span>3. Active Controller 将日志复制给 Follower Controller</span></span>
<span class="line"><span>4. 多数 Follower 确认后，变更提交（Commit）</span></span>
<span class="line"><span>5. Active Controller 通知 Broker 更新元数据缓存</span></span></code></pre></div><hr><h2 id="_5-kraft-vs-zookeeper-模式对比" tabindex="-1">5. KRaft vs ZooKeeper 模式对比 <a class="header-anchor" href="#_5-kraft-vs-zookeeper-模式对比" aria-label="Permalink to &quot;5. KRaft vs ZooKeeper 模式对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比维度</th><th>ZooKeeper 模式</th><th>KRaft 模式</th></tr></thead><tbody><tr><td><strong>外部依赖</strong></td><td>需要独立的 ZooKeeper 集群</td><td>无外部依赖，自包含</td></tr><tr><td><strong>运维复杂度</strong></td><td>高（两套系统）</td><td>低（一套系统）</td></tr><tr><td><strong>Controller 故障恢复</strong></td><td>慢（需全量加载元数据，分钟级）</td><td>快（增量同步，秒级）</td></tr><tr><td><strong>分区扩展上限</strong></td><td>~20 万分区</td><td><strong>百万分区</strong>（官方测试）</td></tr><tr><td><strong>元数据一致性</strong></td><td>ZAB 协议</td><td>Raft 协议</td></tr><tr><td><strong>元数据审计</strong></td><td>不支持</td><td>支持（日志可回放）</td></tr><tr><td><strong>生产可用性</strong></td><td>成熟稳定</td><td>Kafka 3.3+ GA，逐渐成熟</td></tr></tbody></table><hr><h2 id="_6-kraft-配置示例" tabindex="-1">6. KRaft 配置示例 <a class="header-anchor" href="#_6-kraft-配置示例" aria-label="Permalink to &quot;6. KRaft 配置示例&quot;">​</a></h2><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># kraft/server.properties</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 节点角色：controller（纯控制节点）、broker（纯数据节点）、broker,controller（合并部署）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">process.roles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=broker,controller</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 节点 ID（集群内唯一）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">node.id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Controller 节点列表（格式：nodeId@host:port）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">controller.quorum.voters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1@kafka1:9093,2@kafka2:9093,3@kafka3:9093</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 监听地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">listeners</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=PLAINTEXT://:9092,CONTROLLER://:9093</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">inter.broker.listener.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=PLAINTEXT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">controller.listener.names</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=CONTROLLER</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 日志目录</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.dirs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/var/kafka/data</span></span></code></pre></div><p><strong>初始化集群（首次启动必须执行）</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生成唯一的集群 ID</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KAFKA_CLUSTER_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-storage.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> random-uuid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 格式化存储目录（所有节点都要执行）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-storage.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $KAFKA_CLUSTER_ID </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/kafka/kraft/server.properties</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动 Kafka</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-server-start.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/kafka/kraft/server.properties</span></span></code></pre></div><hr><h2 id="_7-迁移-从-zookeeper-模式迁移到-kraft" tabindex="-1">7. 迁移：从 ZooKeeper 模式迁移到 KRaft <a class="header-anchor" href="#_7-迁移-从-zookeeper-模式迁移到-kraft" aria-label="Permalink to &quot;7. 迁移：从 ZooKeeper 模式迁移到 KRaft&quot;">​</a></h2><p>Kafka 3.x 提供了迁移工具，支持<strong>滚动迁移</strong>（不停机）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>迁移步骤（简化）：</span></span>
<span class="line"><span>1. 升级 Kafka 版本到 3.5+</span></span>
<span class="line"><span>2. 部署 KRaft Controller 节点（与现有 ZooKeeper 集群并行运行）</span></span>
<span class="line"><span>3. 将 Broker 配置为同时连接 ZooKeeper 和 KRaft Controller（桥接模式）</span></span>
<span class="line"><span>4. 元数据从 ZooKeeper 迁移到 KRaft</span></span>
<span class="line"><span>5. 逐步将 Broker 切换为纯 KRaft 模式</span></span>
<span class="line"><span>6. 下线 ZooKeeper 集群</span></span></code></pre></div><blockquote><p><strong>生产建议</strong>：新建集群直接使用 KRaft 模式；存量集群可在 Kafka 4.0 之前规划迁移。</p></blockquote><hr><h2 id="_8-常见问题" tabindex="-1">8. 常见问题 <a class="header-anchor" href="#_8-常见问题" aria-label="Permalink to &quot;8. 常见问题&quot;">​</a></h2><p><strong>Q：KRaft 模式下 Controller 宕机，多久能恢复？</strong></p><blockquote><p>KRaft 模式下，Follower Controller 持续同步元数据日志，宕机后只需通过 Raft 选举（通常秒级完成），新 Leader 无需全量加载元数据，恢复速度远快于 ZooKeeper 模式（ZooKeeper 模式可能需要数分钟）。</p></blockquote><p><strong>Q：KRaft 的 Controller 节点数量怎么选？</strong></p><blockquote><p>推荐 <strong>3 个或 5 个</strong> Controller 节点（奇数，满足多数派要求）：</p><ul><li>3 个节点：可容忍 1 个节点故障</li><li>5 个节点：可容忍 2 个节点故障，适合对可用性要求极高的场景</li><li>Controller 节点不需要太多，过多反而增加 Raft 同步开销</li></ul></blockquote><p><strong>Q：KRaft 模式下还能用 ZooKeeper 相关工具吗？</strong></p><blockquote><p>不能。KRaft 模式下没有 ZooKeeper，原来依赖 ZooKeeper 的工具（如 <code>kafka-topics.sh --zookeeper</code>）需要改用 <code>--bootstrap-server</code> 参数。</p></blockquote>`,53)])])}const g=s(i,[["render",r]]);export{c as __pageData,g as default};
